<?php declare(strict_types=1);require_once __DIR__.'/../config/config.php';require_once __DIR__.'/../config/database.php';require_once __DIR__.'/includes/auth.php';$db=db();$e=fn($v)=>htmlspecialchars((string)($v??''),ENT_QUOTES,'UTF-8');if($_SERVER['REQUEST_METHOD']==='POST'){$id=(int)($_POST['id']??0);$name=trim((string)$_POST['name']);$company=trim((string)$_POST['company']);$email=trim((string)$_POST['email']);$phone=trim((string)$_POST['phone']);$status=in_array($_POST['status']??'', ['active','inactive','archived'],true)?$_POST['status']:'active';if($name==='')exit('Client name is required.');if($id){$q=$db->prepare('UPDATE clients SET name=?,company=?,email=?,phone=?,status=? WHERE id=?');$q->execute([$name,$company,$email,$phone,$status,$id]);}else{$q=$db->prepare('INSERT INTO clients(name,company,email,phone,status,public_token) VALUES(?,?,?,?,?,?)');$q->execute([$name,$company,$email,$phone,$status,bin2hex(random_bytes(32))]);}header('Location: clients.php');exit;}$edit=null;if(isset($_GET['edit'])){$q=$db->prepare('SELECT * FROM clients WHERE id=?');$q->execute([(int)$_GET['edit']]);$edit=$q->fetch();}$clients=$db->query('SELECT c.*,COUNT(p.id) project_count FROM clients c LEFT JOIN client_projects p ON p.client_id=c.id GROUP BY c.id ORDER BY c.created_at DESC')->fetchAll();?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Clients</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body class="bg-light"><main class="container py-5"><div class="d-flex justify-content-between align-items-center mb-4"><div><h1 class="h2">Clients</h1><p class="text-muted">Manage active and prospective clients.</p></div></div><div class="card mb-4"><div class="card-body"><h2 class="h5"><?=$edit?'Edit Client':'Add Client'?></h2><form method="post" class="row g-3"><input type="hidden" name="id" value="<?=$e($edit['id']??0)?>"><div class="col-md-6"><label class="form-label">Name</label><input class="form-control" name="name" required value="<?=$e($edit['name']??'')?>"></div><div class="col-md-6"><label class="form-label">Company</label><input class="form-control" name="company" value="<?=$e($edit['company']??'')?>"></div><div class="col-md-4"><label class="form-label">Email</label><input class="form-control" type="email" name="email" value="<?=$e($edit['email']??'')?>"></div><div class="col-md-4"><label class="form-label">Phone</label><input class="form-control" name="phone" value="<?=$e($edit['phone']??'')?>"></div><div class="col-md-4"><label class="form-label">Status</label><select class="form-select" name="status"><?php foreach(['active','inactive','archived'] as $st):?><option <?=$edit&&$edit['status']===$st?'selected':''?>><?=$st?></option><?php endforeach;?></select></div><div class="col-12"><button class="btn btn-dark">Save Client</button></div></form></div></div><div class="card border-0 shadow-sm"><div class="table-responsive"><table class="table mb-0"><thead><tr><th>Client</th><th>Contact</th><th>Projects</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($clients as $c):?><tr><td><strong><?=$e($c['name'])?></strong><div class="text-muted small"><?=$e($c['company'])?></div></td><td><?=$e($c['email'])?><br><?=$e($c['phone'])?></td><td><?=$e($c['project_count'])?></td><td><?=$e($c['status'])?></td><td><a href="?edit=<?=$c['id']?>">Edit</a></td></tr><?php endforeach;?></tbody></table></div></div></main></body></html>